function result=runV4BControlledMechanismPass()
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();p=v4DefaultBParameters();schedule=v4ContinuousPassSchedule(c);state=struct('time',schedule.passStartTimeSec,'phase',0,'cross',struct());errors=zeros(3,4);eligible=0;historyCounts=zeros(0,1);
for frameIndex=1:schedule.frameCount
    ledger=v4RandomLedger(c,'validation',1,1,frameIndex);frame=v4GenerateContinuousFrame(c,state.time,-21,ledger,state.phase,'AWGN');state.time=frame.nextFrameStartTimeSec;state.phase=frame.nextFrameStartPhaseRad;
    if ~schedule.metricEligible(frameIndex),state.cross=struct();continue,end
    eligible=eligible+1;bootstrap=v4CommonBootstrap(frame.observation.rxPhysical(1:8,:),c,SearchStepBins=p.searchStepBins);measurement=schedule.frameStartTimeSec(frameIndex)+4*c.symbolDurationSec;[rate,state.cross]=v4CrossFrameRateUpdate(state.cross,measurement,mean(bootstrap.cfoBins),bootstrap.rateBinsPerSec,c,p);rx=v4DecodeThreeMethods(frame.observation,c,p,Bootstrap=bootstrap,CrossFrameRateBinsPerSec=rate,CrossFrameHistoryCount=state.cross.historyCount);historyCounts(end+1,1)=state.cross.historyCount;for method=1:3,m=v4EvaluateFrame(rx{method},frame.truth,c);errors(method,:)=errors(method,:)+[m.symbolErrors m.hardBitErrors m.softBitErrors m.packetError];end;if mod(eligible,10)==0,fprintf('B controlled AWGN mechanism frames: %d\n',eligible);end
end
den=[eligible*112 eligible*768 eligible*768 eligible];metrics=errors./den;result=struct('status','PASS','channel','AWGN','mode','controlled-time','snrDb',-21,'eligibleFrames',eligible,'methodNames',{c.methodNames},'rawErrors',errors,'denominators',den,'metrics',metrics,'maximumHistoryCount',max(historyCounts),'experimentConditionsFrozen',true);folder=fullfile(root,'results','b_mechanism');if ~isfolder(folder),mkdir(folder);end;save(fullfile(folder,'controlled_awgn_pass.mat'),'result','-v7.3');write(fullfile(folder,'controlled_awgn_pass.json'),jsonencode(result,'PrettyPrint',true));
end
function write(path,text),f=fopen(path,'w','n','UTF-8');cl=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear cl,end
